import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, uniform, vec3, float } from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, Texture, PointLight, Color, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-pricing-row';

  // ---- Parallax-displaced row plane -------------------------------------
  const rowWidth = 2.6;
  const rowHeight = 0.5;

  const mapTex = new Texture();
  const depthTex = new Texture();
  const mapNode = texture(mapTex, uv());
  const depthNode = texture(depthTex, uv());

  const displaceStrength = uniform(0.12);

  const geometry = new PlaneGeometry(rowWidth, rowHeight, 64, 64);

  const rowMaterial = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.42,
    clearcoat: 0.18,
    clearcoatRoughness: 0.4,
    side: DoubleSide,
  });

  // subtle brushed-metal tint from image, blended with base ink color
  rowMaterial.colorNode = vec3(
    mapNode.r.mul(0.35).add(float(colors.ink === '#16161d' ? 0.086 : 0.1)),
    mapNode.g.mul(0.35).add(0.086),
    mapNode.b.mul(0.35).add(0.114)
  );

  // depth-map driven displacement along the normal for a tessellated parallax feel
  rowMaterial.positionNode = positionLocal.add(
    normalLocal.mul(depthNode.r.sub(0.5).mul(displaceStrength))
  );

  const rowPlane = new Mesh(geometry, rowMaterial);
  rowPlane.position.set(0, 0, 0);
  root.add(rowPlane);

  // ---- Subtle divider -----------------------------------------------------
  const dividerGeo = new PlaneGeometry(rowWidth * 0.94, 0.012, 1, 1);
  const dividerMat = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    roughness: 0.8,
    metalness: 0.05,
    transparent: true,
    opacity: 0.22,
  });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -rowHeight * 0.5 + 0.02, 0.01);
  root.add(divider);

  // ---- Accent selection bar (foreground depth plane) ----------------------
  const barGeo = new PlaneGeometry(0.035, rowHeight * 0.7, 1, 1);
  const barMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.1,
    roughness: 0.4,
    metalness: 0.3,
  });
  const accentBar = new Mesh(barGeo, barMat);
  accentBar.position.set(-rowWidth * 0.5 + 0.04, 0, 0.03);
  root.add(accentBar);

  // ---- Node-local rim light (accent hue) -----------------------------------
  const rimLight = new PointLight(new Color(colors.accent), 0.75, 3.2, 2);
  rimLight.position.set(-1.4, 0.35, 1.1);
  root.add(rimLight);

  // ---- Async asset loads ----------------------------------------------------
  let disposed = false;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) return;
      mapTex.image = tex.image;
      mapTex.needsUpdate = true;
      mapNode.value = tex;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      if (disposed) return;
      depthTex.image = tex.image;
      depthTex.needsUpdate = true;
      depthNode.value = tex;
    });
  }

  // ---- Cinematic primitives ---------------------------------------------
  const primitiveHandles = [];
  const parallaxCfg = (config.cinematicPrimitives ?? []).find((p) => p.name === 'parallax-scroll');
  const depthRotateCfg = (config.cinematicPrimitives ?? []).find((p) => p.name === 'depth-rotate');

  primitiveHandles.push(
    ctx.primitives['parallax-scroll'](root, parallaxCfg?.params ?? { intensity: 0.4 })
  );
  primitiveHandles.push(
    ctx.primitives['depth-rotate'](root, depthRotateCfg?.params ?? { maxDeg: 8 })
  );

  // ---- Weighted-settle entrance -------------------------------------------
  root.scale.set(0.98, 0.98, 0.98);
  root.position.y += 0.0;
  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  // ---- Interaction handlers -------------------------------------------------
  const baseY = 0;
  let hoverTl = null;

  const onPointerEnter = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    });
    hoverTl.to(
      barMat,
      { emissiveIntensity: 1.6, duration: 0.3, ease: 'power2.out' },
      0
    );
  };

  const onPointerLeave = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out',
    });
    hoverTl.to(
      barMat,
      { emissiveIntensity: 1.1, duration: 0.3, ease: 'power2.out' },
      0
    );
  };

  const onClick = () => {
    const pressTl = gsap.timeline();
    pressTl.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
      yoyo: true,
      repeat: 1,
    });
    ctx.emit('hub-pricing.select', {
      id: config.id ?? 'hub-pricing-row',
      slotTarget: 'confirmPanel',
    });
  };

  root.userData.handlers = {
    onPointerEnter,
    onPointerOver: onPointerEnter,
    onPointerLeave,
    onPointerOut: onPointerLeave,
    onClick,
  };

  // ---- Cleanup ----------------------------------------------------------
  root.userData.cleanup = () => {
    disposed = true;
    entranceTl.kill();
    if (hoverTl) hoverTl.kill();
    primitiveHandles.forEach((h) => h?.cleanup?.());

    geometry.dispose();
    rowMaterial.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    barGeo.dispose();
    barMat.dispose();

    mapTex.dispose();
    depthTex.dispose();

    root.remove(rimLight);
  };

  return root;
}
